"""Write docs/signals.md from the registry, so the table cannot drift from the code."""

from __future__ import annotations

from pathlib import Path

import efp.signals  # noqa: F401
from efp.signals.registry import registered, signal_function, spec_of

TARGET = Path(__file__).parents[1] / "docs" / "signals.md"
HEADER = (
    "# Signals\n\n"
    "Generated by `scripts/gen_signals_doc.py` from the registry. Do not edit by hand.\n\n"
    "Each signal is winsorized at the 1st and 99th percentiles, sign-aligned so that higher "
    "means higher expected return, and z-scored per rebalance date. A date is dropped for a "
    "signal when it covers under 50% of the universe or under 100 names.\n\n"
    "Month 0 is the month ending at the rebalance date. Spec months `t-12` to `t-2` count from "
    "holding month `t`, so `mom_12_1` covers months 11 to 1 and skips the latest month.\n\n"
    "| Signal | Family | Direction | Definition | Reference | OSAP target |\n"
    "|---|---|---|---|---|---|\n"
)


def render() -> str:
    """The full document."""
    rows = []
    for name in registered():
        spec = spec_of(name)
        doc = (signal_function(name).__doc__ or "").strip().splitlines()[0]
        target = spec.osap_target or "to verify in M5"
        rows.append(
            f"| `{name}` | {spec.family} | {spec.direction:+d} | {doc} | {spec.reference} "
            f"| {target} |"
        )
    return HEADER + "\n".join(rows) + "\n"


if __name__ == "__main__":
    TARGET.write_text(render(), encoding="utf-8", newline="\n")
